local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
function ActivityCakeShopMainLineCell:__init()

end

function ActivityCakeShopMainLineCell:__delete()

end

function ActivityCakeShopMainLineCell:Awake()
    SetButtonAction(self.Root.gameObject,Bind(self,self.OnBtnNodeClick))
end

function ActivityCakeShopMainLineCell:SetLuaIndexAndData(index,data)
    self.index = index
    self.data = data
    self:RefreshShow()
end

function ActivityCakeShopMainLineCell:RefreshShow()
    local showIndex = checkNumber(self.index) >=10 and self.index or "0"..self.index
    self.showIndex = showIndex

    CfUtils.FillText(self.UnSelectChapter,showIndex)
    CfUtils.FillText(self.UnSelectDesc,self.data.name)

    CfUtils.SetUISwitchImage(self.ImgType,1)--self.data.type)
    CfUtils.SetUISwitchImage(self.ImgTitleIcon, self.data.type)
    
    
    self:RefreshIsPass()
    self:RefreshLockState()
end

function ActivityCakeShopMainLineCell:GetIsUnLock()
    local isUnLock = false
    if self.data.unlockLevel == 0 then
        isUnLock = true
    else
        isUnLock = ActivityCakeUtils.IsPassChapter(self.data.unlockLevel)
    end
    return isUnLock
end

function ActivityCakeShopMainLineCell:RefreshIsPass()
    local isPass = ActivityCakeUtils.IsPassChapter(self.data.id)
    CfUtils.SetActive(self.StatusFinish.gameObject,isPass)
end

function ActivityCakeShopMainLineCell:RefreshLockState()

    local isUnLock = self:GetIsUnLock()
    KTool.SetActive(self.StatusLock.gameObject,not isUnLock)

    if not isUnLock then
        CfUtils.SetActive(self.Select.gameObject,false)
        CfUtils.SetActive(self.Unselect.gameObject,true)
        CfUtils.FillText(self.UnSelectChapter,"")
        CfUtils.PlayAnimation(self.Root,"ActivityCakeShopMainLineDetailsDialog_Defualt")
    else

        CfUtils.FillText(self.UnSelectChapter,self.showIndex)
        CfUtils.FillText(self.UnSelectDesc,self.data.name)
        CfUtils.FillText(self.SelectChapter,self.showIndex)
        CfUtils.FillText(self.SelectDesc,self.data.name)
    end
end

function ActivityCakeShopMainLineCell:OnBtnNodeClick()
    if not self:GetIsUnLock() then
        GameUtils.Toast(localize("请先通关前置关卡"))
        return
    end

    if not isNull(self.callBack) then
        self.callBack(self.index)
    end
end

function ActivityCakeShopMainLineCell:SetClickCB(cb)
    self.callBack = cb
end

function ActivityCakeShopMainLineCell:PlayDelayAnimByShow(delayIndex)
    CfUtils.PlayDelayShowAnimation(self.controller, delayIndex, 'UI_List_Cell_ActivityCakeShow')
end

function ActivityCakeShopMainLineCell:PlayAnimByIdle()
    CfUtils.PlayAnimation(self.controller, 'UI_Common_List_Cell_Idle')
end

function ActivityCakeShopMainLineCell:OnSelect()
    CfUtils.PlayAnimation(self.Root,"ActivityCakeShopMainLineDetailsDialog_CellSelect")
    CfUtils.SetActive(self.Select.gameObject,true)
    CfUtils.SetActive(self.Unselect.gameObject,false)
end

function ActivityCakeShopMainLineCell:DoSelect()
    CfUtils.PlayAnimation(self.Root,"ActivityCakeShopMainLineDetailsDialog_CellBack")
    CfUtils.SetActive(self.Select.gameObject,false)
    CfUtils.SetActive(self.Unselect.gameObject,true)
end



